mkdir -p /tmp/bh/model && cat > /tmp/bh/model/model.rs <<'EOF'
use std::collections::BTreeMap;
fn run(n: i32) -> String {
    let mut o = String::new();
    let mut m: BTreeMap<(i32,i32), String> = BTreeMap::new();
    let mut i = 0; while i < n { m.insert((i, i*2), format!("value_{}", i)); i += 1; }
    o += &format!("{}\n", m.len());
    let k1 = (3,6); let k2 = (5,10);
    o += &format!("{}\n", if m.contains_key(&k1) {1} else {0});
    o += &format!("{}\n", if m.contains_key(&k2) {1} else {0});
    let e = m.entry(k1).or_insert_with(String::new).clone();
    o += &format!("{}\n", e);
    m.insert(k1, "modified".to_string());
    o += &format!("{}\n", m[&k1]);
    let nk = m.len(); let nv = m.len();
    o += &format!("{}\n", nk);
    o += &format!("{}\n", nv);
    for i in 0..4 { m.remove(&(i, i*2)); }
    o += &format!("{}\n", m.len());
    if let Some(v) = m.get(&(6,12)) { o += &format!("{}\n", v); }
    if let Some((k,_)) = m.range((6*0+7,14)..).next() { o += &format!("{}\n", k.0); }
    // upper_bound: first key > (7,14)
    if let Some((k,_)) = m.range((std::ops::Bound::Excluded((7,14)), std::ops::Bound::Unbounded)).next() { o += &format!("{}\n", k.0); }
    let mut m2: BTreeMap<(i32,i32), String> = BTreeMap::new();
    let mut i = 0; while i < n/2 { m2.insert((i+10, (i+10)*2), format!("other_{}", i)); i += 1; }
    for (k,v) in &m2 { m.insert(*k, v.clone()); }
    o += &format!("{}\n", m.len());
    o += &format!("{}\n", if m.contains_key(&(12,24)) {1} else {0});
    let cnt = m.range((8,16)..=(8,16)).count();
    o += &format!("{}\n", cnt);
    o += &format!("{}\n", m.get(&(100,200)).cloned().unwrap_or("default".to_string()));
    m.clear();
    o += &format!("{}\n", m.len());
    o += &format!("{}\n", if m.is_empty() {1} else {0});
    o
}
fn main(){ let a: Vec<String> = std::env::args().collect(); let n: i32 = if a.len()>1 { a[1].parse().unwrap_or(0) } else { 18 }; print!("{}", run(n)); }
EOF
